  static int get totalWords => words.length;

  static List<WordTranslation> getWordsByCategory(String category) {
    return words.where((w) => w.category == category).toList();
  }

  static List<WordTranslation> search(String query) {
    final q = query.toLowerCase();
    return words.where((w) =>
      w.wordEn.toLowerCase().contains(q) ||
      w.wordFr.toLowerCase().contains(q) ||
      w.wordTr.toLowerCase().contains(q)
    ).toList();
  }

  static WordTranslation? getByEnglish(String word) {
    try {
      return words.firstWhere((w) => w.wordEn.toLowerCase() == word.toLowerCase());
    } catch (_) {
      return null;
    }
  }
